function(container, apiUrl, tables) {
  const docSelect = container.querySelector('#doc-select');
  const version1Select = container.querySelector('#version1-select');
  const version2Select = container.querySelector('#version2-select');
  const compareBtn = container.querySelector('#compare-btn');
  const version1Content = container.querySelector('#version1-content');
  const version2Content = container.querySelector('#version2-content');
  const changesList = container.querySelector('#changes-list');
  const v1Meta = container.querySelector('#v1-meta');
  const v2Meta = container.querySelector('#v2-meta');

  let contractVersions = [];
  let proposalVersions = [];

  // 初期化: バージョンデータを取得
  async function init() {
    try {
      // 契約書バージョンを取得（tableIndex: 4）
      contractVersions = await window.aivicApi.list(4) || [];
      // 提案資料バージョンを取得（tableIndex: 5）
      proposalVersions = await window.aivicApi.list(5) || [];
    } catch (e) {
      console.error('バージョンデータ取得エラー:', e);
    }
  }

  // ドキュメント種別変更時
  docSelect.addEventListener('change', async (e) => {
    const docType = e.target.value;
    version1Select.innerHTML = '<option value="">選択してください</option>';
    version2Select.innerHTML = '<option value="">選択してください</option>';
    version1Content.innerHTML = '<span style="color: var(--text-muted);">バージョンを選択してください</span>';
    version2Content.innerHTML = '<span style="color: var(--text-muted);">バージョンを選択してください</span>';
    changesList.innerHTML = '<div style="padding: 8px 12px; font-size: 12px; color: var(--text-muted);">変更箇所はここに表示されます</div>';

    const versions = docType === 'contract' ? contractVersions : proposalVersions;
    versions.forEach(v => {
      const opt1 = document.createElement('option');
      opt1.value = v.id;
      opt1.textContent = `v${v.バージョン番号 || v.version_number} (${new Date(v.作成日時 || v.created_at).toLocaleDateString('ja-JP')})`;
      version1Select.appendChild(opt1);

      const opt2 = document.createElement('option');
      opt2.value = v.id;
      opt2.textContent = `v${v.バージョン番号 || v.version_number} (${new Date(v.作成日時 || v.created_at).toLocaleDateString('ja-JP')})`;
      version2Select.appendChild(opt2);
    });
  });

  // 比較実行
  compareBtn.addEventListener('click', async () => {
    const docType = docSelect.value;
    const v1Id = version1Select.value;
    const v2Id = version2Select.value;

    if (!docType || !v1Id || !v2Id) {
      alert('ドキュメント種別とバージョンを選択してください');
      return;
    }

    const versions = docType === 'contract' ? contractVersions : proposalVersions;
    const v1 = versions.find(v => v.id === v1Id);
    const v2 = versions.find(v => v.id === v2Id);

    if (!v1 || !v2) return;

    // コンテンツ取得（契約書はファイルパス、提案資料は内容フィールド）
    const content1 = docType === 'contract' 
      ? (v1.変更内容 || v1.change_description || '（ファイルベース）')
      : (v1.内容 || v1.content || '');
    const content2 = docType === 'contract'
      ? (v2.変更内容 || v2.change_description || '（ファイルベース）')
      : (v2.内容 || v2.content || '');

    // メタ情報表示
    v1Meta.textContent = `v${v1.バージョン番号 || v1.version_number} • ${new Date(v1.作成日時 || v1.created_at).toLocaleDateString('ja-JP')}`;
    v2Meta.textContent = `v${v2.バージョン番号 || v2.version_number} • ${new Date(v2.作成日時 || v2.created_at).toLocaleDateString('ja-JP')}`;

    // 差分計算（簡易行ベース）
    const lines1 = (content1 || '').split('\n');
    const lines2 = (content2 || '').split('\n');

    // LCS風の簡易差分検出
    const changes = [];
    const maxLen = Math.max(lines1.length, lines2.length);

    for (let i = 0; i < maxLen; i++) {
      const line1 = lines1[i] || '';
      const line2 = lines2[i] || '';

      if (line1 !== line2) {
        if (!line1 && line2) {
          changes.push({ type: 'added', line: line2, index: i });
        } else if (line1 && !line2) {
          changes.push({ type: 'deleted', line: line1, index: i });
        } else {
          changes.push({ type: 'modified', line1, line2, index: i });
        }
      }
    }

    // コンテンツ表示（ハイライト付き）
    const renderContent = (lines, changes, isV1) => {
      return lines.map((line, i) => {
        const change = changes.find(c => c.index === i);
        if (!change) return line;

        if (isV1) {
          if (change.type === 'deleted') {
            return `<span style="background: rgba(229, 115, 115, 0.3); border-left: 2px solid #e57373; padding-left: 4px; display: block; margin: 2px 0;">${line}</span>`;
          } else if (change.type === 'modified') {
            return `<span style="background: rgba(255, 183, 77, 0.3); border-left: 2px solid #ffb74d; padding-left: 4px; display: block; margin: 2px 0;">${line}</span>`;
          }
        } else {
          if (change.type === 'added') {
            return `<span style="background: rgba(129, 199, 132, 0.3); border-left: 2px solid #81c784; padding-left: 4px; display: block; margin: 2px 0;">${line}</span>`;
          } else if (change.type === 'modified') {
            return `<span style="background: rgba(255, 183, 77, 0.3); border-left: 2px solid #ffb74d; padding-left: 4px; display: block; margin: 2px 0;">${line}</span>`;
          }
        }
        return line;
      }).join('\n');
    };

    version1Content.innerHTML = renderContent(lines1, changes, true);
    version2Content.innerHTML = renderContent(lines2, changes, false);

    // 変更箇所一覧
    changesList.innerHTML = changes.length === 0
      ? '<div style="padding: 8px 12px; font-size: 12px; color: var(--text-muted);">変更なし</div>'
      : changes.map((c, idx) => {
          let label = '';
          let bgColor = '';
          if (c.type === 'added') {
            label = '追加';
            bgColor = 'rgba(129, 199, 132, 0.15)';
          } else if (c.type === 'deleted') {
            label = '削除';
            bgColor = 'rgba(229, 115, 115, 0.15)';
          } else {
            label = '変更';
            bgColor = 'rgba(255, 183, 77, 0.15)';
          }
          return `<div style="padding: 8px 12px; border-bottom: 1px solid var(--border); background: ${bgColor}; font-size: 12px;">
            <span style="display: inline-block; background: var(--primary); color: #fff; padding: 2px 6px; border-radius: 3px; font-weight: 600; margin-right: 6px; font-size: 10px;">${label}</span>
            <span style="color: var(--text-muted);">行 ${c.index + 1}</span>
            <div style="margin-top: 4px; color: var(--text); font-size: 11px; word-break: break-word;">
              ${c.type === 'modified' ? `<div><strong>変更前:</strong> ${c.line1}</div><div><strong>変更後:</strong> ${c.line2}</div>` : c.line}
            </div>
          </div>`;
        }).join('');
  });

  init();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const CONTRACT_TABLE = 0;
  const PROPOSAL_TABLE = 1;
  const CONTRACT_VERSION_TABLE = 2;
  const PROPOSAL_VERSION_TABLE = 3;
  const CHANGE_HISTORY_TABLE = 4;
  const USER_TABLE = 5;

  let currentDocType = 'contract';
  let currentDocId = null;
  let currentFile = null;
  let currentUser = null;

  // DOM要素
  const tabBtns = container.querySelectorAll('.tab-btn');
  const documentList = container.querySelector('#document-list');
  const changeTimeline = container.querySelector('#change-timeline');
  const selectedDocName = container.querySelector('#selected-doc-name');
  const selectedDocId = container.querySelector('#selected-doc-id');
  const selectedDocType = container.querySelector('#selected-doc-type');
  const versionForm = container.querySelector('#version-form');
  const versionNumber = container.querySelector('#version-number');
  const changeContent = container.querySelector('#change-content');
  const changeReason = container.querySelector('#change-reason');
  const fileDropZone = container.querySelector('#file-drop-zone');
  const fileInput = container.querySelector('#file-input');
  const fileName = container.querySelector('#file-name');
  const approverSelect = container.querySelector('#approver-select');
  const currentUserEl = container.querySelector('#current-user');
  const currentDatetimeEl = container.querySelector('#current-datetime');
  const saveBtn = container.querySelector('#save-btn');
  const cancelBtn = container.querySelector('#cancel-btn');
  const confirmDialog = container.querySelector('#confirm-dialog');
  const confirmMessage = container.querySelector('#confirm-message');
  const confirmOk = container.querySelector('#confirm-ok');
  const confirmCancel = container.querySelector('#confirm-cancel');
  const successMessage = container.querySelector('#success-message');
  const errorMessage = container.querySelector('#error-message');

  // 初期化
  async function init() {
    // 現在のユーザー情報を取得（ダミー）
    currentUser = {
      id: 'user-current',
      name: '山田太郎'
    };
    currentUserEl.textContent = currentUser.name;
    updateCurrentDatetime();

    // タブ切り替え
    tabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        tabBtns.forEach(b => {
          b.style.background = 'transparent';
          b.style.color = 'var(--text)';
          b.style.border = '1px solid var(--border)';
        });
        btn.style.background = 'var(--primary)';
        btn.style.color = '#fff';
        btn.style.border = 'none';
        currentDocType = btn.dataset.type;
        currentDocId = null;
        resetForm();
        loadDocumentList();
      });
    });

    // ファイルドラッグ&ドロップ
    fileDropZone.addEventListener('dragover', (e) => {
      e.preventDefault();
      fileDropZone.style.background = 'rgba(212, 175, 55, 0.15)';
      fileDropZone.style.borderColor = 'var(--primary)';
    });
    fileDropZone.addEventListener('dragleave', () => {
      fileDropZone.style.background = 'rgba(212, 175, 55, 0.05)';
      fileDropZone.style.borderColor = 'rgba(212, 175, 55, 0.4)';
    });
    fileDropZone.addEventListener('drop', (e) => {
      e.preventDefault();
      fileDropZone.style.background = 'rgba(212, 175, 55, 0.05)';
      fileDropZone.style.borderColor = 'rgba(212, 175, 55, 0.4)';
      const files = e.dataTransfer.files;
      if (files.length > 0) {
        handleFileSelect(files[0]);
      }
    });
    fileDropZone.addEventListener('click', () => {
      fileInput.click();
    });
    fileInput.addEventListener('change', (e) => {
      if (e.target.files.length > 0) {
        handleFileSelect(e.target.files[0]);
      }
    });

    // ボタンイベント
    saveBtn.addEventListener('click', showConfirmDialog);
    cancelBtn.addEventListener('click', resetForm);
    confirmOk.addEventListener('click', saveVersion);
    confirmCancel.addEventListener('click', hideConfirmDialog);

    // 初期表示
    loadDocumentList();
  }

  // 資料一覧を読み込み
  async function loadDocumentList() {
    documentList.innerHTML = '';
    const tableIndex = currentDocType === 'contract' ? CONTRACT_TABLE : PROPOSAL_TABLE;
    const docs = await window.aivicApi.list(tableIndex);

    if (!docs || docs.length === 0) {
      documentList.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); padding: 8px; text-align: center;">資料がありません</div>';
      return;
    }

    docs.forEach(doc => {
      const docItem = document.createElement('div');
      docItem.dataset.id = doc.id;
      docItem.style.cssText = `
        padding: 10px;
        background: var(--bg-card);
        border: 1px solid var(--border);
        border-radius: 4px;
        cursor: pointer;
        transition: all 0.2s;
        font-size: 12px;
      `;
      const docName = currentDocType === 'contract' ? doc['契約書名'] : doc['提案資料名'];
      const docStatus = doc['ステータス'] || '草案';
      docItem.innerHTML = `
        <div style="font-weight: 600; color: var(--text); margin-bottom: 4px;">${docName}</div>
        <div style="font-size: 11px; color: var(--text-muted);">ステータス: ${docStatus}</div>
      `;
      docItem.addEventListener('click', () => selectDocument(doc));
      docItem.addEventListener('mouseover', () => {
        docItem.style.background = 'var(--bg-main)';
        docItem.style.borderColor = 'var(--primary)';
      });
      docItem.addEventListener('mouseout', () => {
        docItem.style.background = 'var(--bg-card)';
        docItem.style.borderColor = 'var(--border)';
      });
      documentList.appendChild(docItem);
    });
  }

  // 資料を選択
  async function selectDocument(doc) {
    currentDocId = doc.id;
    selectedDocId.value = doc.id;
    selectedDocType.value = currentDocType;
    const docName = currentDocType === 'contract' ? doc['契約書名'] : doc['提案資料名'];
    selectedDocName.textContent = docName;

    // 変更履歴を読み込み
    loadChangeHistory();

    // 次のバージョン番号を推測
    const versionTableIndex = currentDocType === 'contract' ? CONTRACT_VERSION_TABLE : PROPOSAL_VERSION_TABLE;
    const versions = await window.aivicApi.list(versionTableIndex);
    const docVersions = versions ? versions.filter(v => v['契約書ID'] === doc.id || v['提案資料ID'] === doc.id) : [];
    const nextVersion = docVersions.length > 0 ? Math.max(...docVersions.map(v => v['バージョン番号'] || 0)) + 1 : 1;
    versionNumber.value = nextVersion;
  }

  // 変更履歴を読み込み
  async function loadChangeHistory() {
    changeTimeline.innerHTML = '';
    const historyData = await window.aivicApi.list(CHANGE_HISTORY_TABLE);
    const docHistories = historyData ? historyData.filter(h => h['対象ID'] === currentDocId) : [];

    if (docHistories.length === 0) {
      changeTimeline.innerHTML = '<div style="font-size: 11px; color: var(--text-muted); text-align: center; padding: 8px;">変更履歴がありません</div>';
      return;
    }

    // 新しい順にソート
    docHistories.sort((a, b) => new Date(b['作成日時']) - new Date(a['作成日時']));

    docHistories.slice(0, 5).forEach((history, idx) => {
      const timelineItem = document.createElement('div');
      timelineItem.style.cssText = `
        padding: 8px;
        background: var(--bg-card);
        border-left: 2px solid var(--primary);
        border-radius: 2px;
        position: relative;
      `;
      const date = new Date(history['作成日時']).toLocaleString('ja-JP', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
      timelineItem.innerHTML = `
        <div style="font-size: 10px; color: var(--text-muted); margin-bottom: 2px;">${date}</div>
        <div style="font-size: 11px; color: var(--text); margin-bottom: 2px; font-weight: 600;">${history['変更種別']}</div>
        <div style="font-size: 10px; color: var(--text-muted);">${history['変更理由'] || '—'}</div>
      `;
      changeTimeline.appendChild(timelineItem);
    });
  }

  // ファイル選択処理
  function handleFileSelect(file) {
    currentFile = file;
    fileName.textContent = `✓ ${file.name}`;
    fileName.style.color = 'var(--success)';
  }

  // フォームをリセット
  function resetForm() {
    versionForm.reset();
    currentFile = null;
    fileName.textContent = '';
    currentDocId = null;
    selectedDocId.value = '';
    selectedDocType.value = '';
    selectedDocName.textContent = '資料を選択してください';
    changeTimeline.innerHTML = '';
  }

  // 確認ダイアログを表示
  function showConfirmDialog() {
    if (!currentDocId) {
      showError('資料を選択してください');
      return;
    }
    if (!versionNumber.value) {
      showError('バージョン番号を入力してください');
      return;
    }
    if (!changeContent.value.trim()) {
      showError('変更内容を入力してください');
      return;
    }

    const msg = `
      <strong>バージョン ${versionNumber.value}</strong><br/>
      変更内容: ${changeContent.value.substring(0, 50)}${changeContent.value.length > 50 ? '...' : ''}<br/>
      ファイル: ${currentFile ? currentFile.name : 'なし'}<br/>
      承認者: ${approverSelect.options[approverSelect.selectedIndex].text}
    `;
    confirmMessage.innerHTML = msg;
    confirmDialog.style.display = 'flex';
  }

  // 確認ダイアログを非表示
  function hideConfirmDialog() {
    confirmDialog.style.display = 'none';
  }

  // バージョンを保存
  async function saveVersion() {
    hideConfirmDialog();

    const versionData = {
      [currentDocType === 'contract' ? '契約書ID' : '提案資料ID']: currentDocId,
      'バージョン番号': parseInt(versionNumber.value),
      '変更内容': changeContent.value,
      'ステータス': 'レビュー中',
      '作成者ID': currentUser.id,
      '作成日時': new Date().toISOString(),
      '更新日時': new Date().toISOString(),
      '承認者ID': approverSelect.value || null
    };

    if (currentFile) {
      versionData['ファイルパス'] = `uploads/${currentFile.name}`;
    }

    const versionTableIndex = currentDocType === 'contract' ? CONTRACT_VERSION_TABLE : PROPOSAL_VERSION_TABLE;
    const saved = await window.aivicApi.save(versionTableIndex, versionData);

    if (saved) {
      // 変更履歴を記録
      const historyData = {
        '対象テーブル': currentDocType === 'contract' ? '契約書' : '提案資料',
        '対象ID': currentDocId,
        '変更種別': 'バージョン作成',
        '変更フィールド': 'バージョン',
        '変更前値': '',
        '変更後値': `v${versionNumber.value}`,
        '変更理由': changeReason.value,
        '作成者ID': currentUser.id,
        '作成日時': new Date().toISOString()
      };
      await window.aivicApi.save(CHANGE_HISTORY_TABLE, historyData);

      showSuccess();
      resetForm();
      loadDocumentList();
      setTimeout(() => {
        window.showScreen('scr-1782623175064');
      }, 1500);
    } else {
      showError('保存に失敗しました');
    }
  }

  // 日時を更新
  function updateCurrentDatetime() {
    const now = new Date();
    currentDatetimeEl.textContent = now.toLocaleString('ja-JP', {
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 成功メッセージを表示
  function showSuccess() {
    successMessage.style.display = 'block';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // エラーメッセージを表示
  function showError(msg) {
    errorMessage.textContent = msg;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 3000);
  }

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  const contractTableIdx = 0;  // 契約書テーブル
  const proposalTableIdx = 1; // 提案資料テーブル
  const changeLogTableIdx = 2; // 変更履歴テーブル
  const userTableIdx = 3;      // ユーザーテーブル

  // DOM 要素取得
  const keywordInput = container.querySelector('[data-testid="keyword-input"]');
  const docTypeSelect = container.querySelector('[data-testid="document-type-select"]');
  const statusSelect = container.querySelector('[data-testid="status-select"]');
  const createdDateFrom = container.querySelector('[data-testid="created-date-from"]');
  const searchBtn = container.querySelector('[data-testid="search-button"]');
  const exportBtn = container.querySelector('[data-testid="export-csv-button"]');
  const resultsTable = container.querySelector('[data-testid="record-list"]');
  const resultsTbody = container.querySelector('#search-results-tbody');

  const detailModal = container.querySelector('#detail-modal');
  const closeDetailBtn = container.querySelector('#close-detail-btn');
  const detailCloseBtn = container.querySelector('#detail-close-btn');
  const detailEditBtn = container.querySelector('#detail-edit-btn');

  // ユーザーマップ（ID → 名前）
  let userMap = {};

  // 初期化: ユーザーデータ取得
  async function initUsers() {
    const users = await window.aivicApi.list(userTableIdx);
    if (users) {
      users.forEach(u => {
        userMap[u.ユーザーID] = u.ユーザー名 || u.メールアドレス;
      });
    }
  }

  // 検索実行
  async function performSearch() {
    const keyword = keywordInput.value.trim().toLowerCase();
    const docType = docTypeSelect.value;
    const status = statusSelect.value;
    const dateFrom = createdDateFrom.value;

    resultsTbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted);">検索中...</td></tr>';

    try {
      const contracts = await window.aivicApi.list(contractTableIdx) || [];
      const proposals = await window.aivicApi.list(proposalTableIdx) || [];

      // 統合リスト（type フィールドを追加）
      let results = [];

      // 契約書
      if (!docType || docType === 'contract') {
        contracts.forEach(c => {
          results.push({
            id: c.契約書ID,
            type: 'contract',
            name: c.契約書名,
            description: c.契約書説明 || '',
            status: c.ステータス,
            createdAt: c.作成日時,
            updatedAt: c.更新日時,
            ownerId: c.担当者ID,
            creatorId: c.作成者ID,
            originalData: c
          });
        });
      }

      // 提案資料
      if (!docType || docType === 'proposal') {
        proposals.forEach(p => {
          results.push({
            id: p.提案資料ID,
            type: 'proposal',
            name: p.提案資料名,
            description: p.説明 || '',
            status: p.ステータス,
            createdAt: p.作成日時,
            updatedAt: p.更新日時,
            ownerId: p.ユーザーID,
            creatorId: p.作成者ID,
            originalData: p
          });
        });
      }

      // フィルタリング
      results = results.filter(r => {
        const matchKeyword = !keyword || 
          r.name.toLowerCase().includes(keyword) || 
          r.description.toLowerCase().includes(keyword);

        const matchStatus = !status || r.status === status;

        const matchDate = !dateFrom || new Date(r.createdAt) >= new Date(dateFrom);

        return matchKeyword && matchStatus && matchDate;
      });

      // ソート（最新順）
      results.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt));

      // テーブル描画
      if (results.length === 0) {
        resultsTbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する資料がありません</td></tr>';
        return;
      }

      resultsTbody.innerHTML = results.map((r, idx) => {
        const typeLabel = r.type === 'contract' ? '契約書' : '提案資料';
        const statusLabel = {
          draft: '下書き',
          pending: '承認待ち',
          approved: '承認済み',
          active: '有効',
          rejected: '却下',
          expired: '終了'
        }[r.status] || r.status;

        const createdDate = new Date(r.createdAt).toLocaleDateString('ja-JP');
        const updatedDate = new Date(r.updatedAt).toLocaleDateString('ja-JP');

        const bgColor = idx % 2 === 0 ? 'var(--bg-card)' : 'rgba(212, 175, 55, 0.03)';

        return `
          <tr data-id="${r.id}" data-type="${r.type}" style="background: ${bgColor}; cursor: pointer; border-bottom: 1px solid var(--border);">
            <td style="padding: 10px; color: var(--text);">${escapeHtml(r.name)}</td>
            <td style="padding: 10px; color: var(--text-muted); font-size: 12px;">${typeLabel}</td>
            <td style="padding: 10px;">
              <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; font-size: 11px; font-weight: 500; background: rgba(212, 175, 55, 0.15); color: var(--primary);">
                ${statusLabel}
              </span>
            </td>
            <td style="padding: 10px; color: var(--text-muted); font-size: 12px;">${createdDate}</td>
            <td style="padding: 10px; color: var(--text-muted); font-size: 12px;">${updatedDate}</td>
            <td style="padding: 10px; text-align: center;">
              <button class="view-detail-btn" data-id="${r.id}" data-type="${r.type}" style="background: transparent; border: none; color: var(--primary); cursor: pointer; font-size: 12px; text-decoration: underline;">
                詳細
              </button>
            </td>
          </tr>
        `;
      }).join('');

      // 詳細ボタンのイベント
      resultsTbody.querySelectorAll('.view-detail-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
          e.stopPropagation();
          const id = btn.dataset.id;
          const type = btn.dataset.type;
          showDetail(id, type);
        });
      });

      // 行クリックでも詳細表示
      resultsTbody.querySelectorAll('tr[data-id]').forEach(row => {
        row.addEventListener('click', () => {
          const id = row.dataset.id;
          const type = row.dataset.type;
          showDetail(id, type);
        });
      });

    } catch (err) {
      console.error('Search error:', err);
      resultsTbody.innerHTML = '<tr style="background: var(--bg-card);"><td colspan="6" style="padding: 20px; text-align: center; color: var(--error);">検索に失敗しました</td></tr>';
    }
  }

  // 詳細表示
  async function showDetail(id, type) {
    const contracts = await window.aivicApi.list(contractTableIdx) || [];
    const proposals = await window.aivicApi.list(proposalTableIdx) || [];
    const changeLogs = await window.aivicApi.list(changeLogTableIdx) || [];

    let record = null;
    if (type === 'contract') {
      record = contracts.find(c => c.契約書ID === id);
    } else {
      record = proposals.find(p => p.提案資料ID === id);
    }

    if (!record) return;

    // 基本情報を詳細パネルに設定
    const typeLabel = type === 'contract' ? '契約書' : '提案資料';
    const statusLabel = {
      draft: '下書き',
      pending: '承認待ち',
      approved: '承認済み',
      active: '有効',
      rejected: '却下',
      expired: '終了'
    }[record.ステータス] || record.ステータス;

    container.querySelector('#detail-title').textContent = record.契約書名 || record.提案資料名;
    container.querySelector('#detail-id').textContent = id;
    container.querySelector('#detail-type').textContent = typeLabel;
    container.querySelector('#detail-status').textContent = statusLabel;
    container.querySelector('#detail-created').textContent = new Date(record.作成日時).toLocaleString('ja-JP');
    container.querySelector('#detail-updated').textContent = new Date(record.更新日時).toLocaleString('ja-JP');
    container.querySelector('#detail-owner').textContent = userMap[record.担当者ID || record.ユーザーID] || '—';
    container.querySelector('#detail-creator').textContent = userMap[record.作成者ID] || '—';
    container.querySelector('#detail-description').textContent = record.契約書説明 || record.説明 || '—';

    // 変更履歴タイムライン
    const relatedLogs = changeLogs.filter(log => log.対象ID === id);
    const timelineHtml = relatedLogs.length === 0 
      ? '<p style="font-size: 12px; color: var(--text-muted); text-align: center;">変更履歴がありません</p>'
      : relatedLogs.map(log => {
          const date = new Date(log.作成日時).toLocaleString('ja-JP');
          const creator = userMap[log.作成者ID] || '不明';
          return `
            <div style="padding: 10px; border-left: 2px solid var(--primary); background: rgba(212, 175, 55, 0.05); border-radius: 4px;">
              <p style="font-size: 12px; color: var(--text-muted); margin: 0 0 4px 0;">${date} / ${creator}</p>
              <p style="font-size: 12px; color: var(--text); margin: 0 0 4px 0; font-weight: 500;">${log.変更種別}</p>
              ${log.変更フィールド ? `<p style="font-size: 11px; color: var(--text-muted); margin: 0 0 2px 0;"><strong>${log.変更フィールド}:</strong> ${log.変更前値} → ${log.変更後値}</p>` : ''}
              ${log.変更理由 ? `<p style="font-size: 11px; color: var(--text-muted); margin: 0;">理由: ${log.変更理由}</p>` : ''}
            </div>
          `;
        }).join('');

    container.querySelector('#detail-timeline').innerHTML = timelineHtml;

    // 編集ボタン
    detailEditBtn.onclick = () => {
      detailModal.style.display = 'none';
      if (type === 'contract') {
        window.showScreen('scr-1782623175064'); // 契約書・提案資料管理画面
      } else {
        window.showScreen('scr-1782623175064');
      }
    };

    // モーダル表示
    detailModal.style.display = 'flex';
  }

  // モーダル閉じる
  function closeModal() {
    detailModal.style.display = 'none';
  }

  closeDetailBtn.addEventListener('click', closeModal);
  detailCloseBtn.addEventListener('click', closeModal);

  // Esc キーでも閉じる
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && detailModal.style.display !== 'none') {
      closeModal();
    }
  });

  // overlay クリックで閉じる
  detailModal.addEventListener('click', (e) => {
    if (e.target === detailModal) {
      closeModal();
    }
  });

  // 検索ボタン
  searchBtn.addEventListener('click', performSearch);

  // Enter キーでも検索
  keywordInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') performSearch();
  });

  // CSV エクスポート
  exportBtn.addEventListener('click', async () => {
    try {
      const contracts = await window.aivicApi.list(contractTableIdx) || [];
      const proposals = await window.aivicApi.list(proposalTableIdx) || [];

      // 統合データ
      let rows = [];
      contracts.forEach(c => {
        rows.push({
          '資料ID': c.契約書ID,
          '資料名': c.契約書名,
          '種別': '契約書',
          'ステータス': c.ステータス,
          '作成日': new Date(c.作成日時).toLocaleDateString('ja-JP'),
          '最終更新': new Date(c.更新日時).toLocaleDateString('ja-JP'),
          '担当者': userMap[c.担当者ID] || '—',
          '説明': c.契約書説明 || ''
        });
      });

      proposals.forEach(p => {
        rows.push({
          '資料ID': p.提案資料ID,
          '資料名': p.提案資料名,
          '種別': '提案資料',
          'ステータス': p.ステータス,
          '作成日': new Date(p.作成日時).toLocaleDateString('ja-JP'),
          '最終更新': new Date(p.更新日時).toLocaleDateString('ja-JP'),
          '担当者': userMap[p.ユーザーID] || '—',
          '説明': p.説明 || ''
        });
      });

      // CSV 生成
      const headers = Object.keys(rows[0] || {});
      const csv = '\uFEFF' + headers.join(',') + '\n' + rows.map(row => 
        headers.map(h => {
          const val = row[h] || '';
          return val.includes(',') || val.includes('"') || val.includes('\n') 
            ? `"${val.replace(/"/g, '""')}"` 
            : val;
        }).join(',')
      ).join('\n');

      // ダウンロード
      const blob = new Blob([csv], { type: 'text/csv; charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `資料検索結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (err) {
      console.error('Export error:', err);
    }
  });

  // HTML エスケープ
  function escapeHtml(text) {
    const map = {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#039;'
    };
    return text.replace(/[&<>"']/g, m => map[m]);
  }

  // 初期化
  initUsers();
}

function(container, apiUrl, tables) {
  const templateListEl = container.querySelector('#template-list');
  const templateNameInput = container.querySelector('[data-testid="template-name"]');
  const templateDescInput = container.querySelector('[data-testid="template-description"]');
  const templateCategorySelect = container.querySelector('[data-testid="template-category"]');
  const templateContentInput = container.querySelector('[data-testid="template-content"]');
  const previewPane = container.querySelector('#preview-pane');
  const tabBtns = container.querySelectorAll('.tab-btn');
  const tabContents = container.querySelectorAll('.tab-content');
  const saveBtn = container.querySelector('[data-testid="save-button"]');
  const cancelBtn = container.querySelector('[data-testid="cancel-button"]');
  const newTemplateBtn = container.querySelector('[data-testid="new-template-btn"]');
  const addApprovalStepBtn = container.querySelector('[data-testid="add-approval-step"]');
  const deleteConfirmModal = container.querySelector('#delete-confirm-modal');
  const closeModalBtns = container.querySelectorAll('.close-modal');
  const statusEl = container.querySelector('#template-status');

  let currentTemplateId = null;
  let allTemplates = [];
  let approvalStepCounter = 0;

  // テンプレートデータ構造
  const templateStructure = {
    id: null,
    name: '',
    description: '',
    category: '',
    content: '',
    departments: [],
    requiredFields: ['contract_date', 'party_a', 'party_b', 'amount'],
    conditionalFields: [],
    approvalFlow: [],
    requireLegalReview: false,
    requireFinanceReview: false,
    autoArchive: false,
    versionControl: false,
  };

  // テンプレート一覧を読み込む
  async function loadTemplates() {
    const templates = await window.aivicApi.list(0); // 契約書テーブル
    allTemplates = templates || [];
    renderTemplateList();
  }

  // テンプレート一覧を描画
  function renderTemplateList() {
    templateListEl.innerHTML = '';
    allTemplates.forEach(template => {
      const item = document.createElement('div');
      item.className = 'template-item';
      item.dataset.id = template.id;
      item.style.cssText = `
        padding: 10px;
        background: ${currentTemplateId === template.id ? 'var(--primary)' : 'var(--bg-card)'};
        color: ${currentTemplateId === template.id ? '#fff' : 'var(--text)'};
        border-radius: 4px;
        cursor: pointer;
        font-size: 13px;
        font-weight: 500;
        transition: all 0.2s;
        border: 1px solid ${currentTemplateId === template.id ? 'var(--primary)' : 'transparent'};
      `;
      item.textContent = template.contract_name || '(無名)';
      item.addEventListener('click', () => selectTemplate(template));
      templateListEl.appendChild(item);
    });
  }

  // テンプレートを選択
  function selectTemplate(template) {
    currentTemplateId = template.id;
    templateNameInput.value = template.contract_name || '';
    templateDescInput.value = template.contract_description || '';
    templateCategorySelect.value = template.contract_type || '';
    templateContentInput.value = template.file_path || ''; // 簡略化: ファイルパスを本文として扱う
    statusEl.textContent = `選択中: ${template.contract_name}`;
    updatePreview();
    renderTemplateList();
    switchTab('basic');
  }

  // 新規テンプレート作成
  newTemplateBtn.addEventListener('click', () => {
    currentTemplateId = null;
    templateNameInput.value = '';
    templateDescInput.value = '';
    templateCategorySelect.value = '';
    templateContentInput.value = '';
    container.querySelectorAll('.department-check').forEach(cb => cb.checked = false);
    container.querySelectorAll('.required-field').forEach(cb => cb.checked = false);
    container.querySelectorAll('.conditional-field').forEach(cb => cb.checked = false);
    container.querySelector('#require-legal-review').checked = false;
    container.querySelector('#require-finance-review').checked = false;
    container.querySelector('#auto-archive').checked = false;
    container.querySelector('#version-control').checked = false;
    container.querySelector('#approval-flow-container').innerHTML = '';
    approvalStepCounter = 0;
    statusEl.textContent = '新規テンプレート作成中';
    updatePreview();
    renderTemplateList();
    switchTab('basic');
  });

  // タブ切り替え
  function switchTab(tabName) {
    tabContents.forEach(tc => tc.style.display = 'none');
    tabBtns.forEach(btn => {
      btn.style.borderBottomColor = 'transparent';
      btn.style.color = 'var(--text-muted)';
    });
    container.querySelector(`[data-tab="${tabName}"]`).style.display = 'block';
    const activeBtn = container.querySelector(`[data-tab="${tabName}"].tab-btn`);
    if (activeBtn) {
      activeBtn.style.borderBottomColor = 'var(--primary)';
      activeBtn.style.color = 'var(--text)';
    }
  }

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => switchTab(btn.dataset.tab));
  });

  // プレビュー更新
  function updatePreview() {
    let preview = templateContentInput.value;
    if (!preview) {
      preview = 'テンプレート本文を入力すると、ここにプレビューが表示されます。';
    }
    previewPane.textContent = preview;
  }

  templateContentInput.addEventListener('input', updatePreview);

  // 承認ステップを追加
  addApprovalStepBtn.addEventListener('click', () => {
    approvalStepCounter++;
    const stepContainer = document.createElement('div');
    stepContainer.className = 'approval-step';
    stepContainer.style.cssText = `
      padding: 12px;
      background: var(--bg-main);
      border: 1px solid var(--border);
      border-radius: 4px;
      display: grid;
      grid-template-columns: 1fr 1fr auto;
      gap: 8px;
      align-items: end;
    `;
    stepContainer.innerHTML = `
      <div>
        <label style="display: block; font-size: 11px; font-weight: 600; color: var(--text-muted); margin-bottom: 4px;">ステップ ${approvalStepCounter}</label>
        <input type="text" placeholder="例: 法務部長" class="approval-step-name" style="width: 100%; padding: 6px 8px; background: var(--bg-card); border: 1px solid rgba(212, 175, 55, 0.25); border-radius: 3px; color: var(--text); font-size: 12px; box-sizing: border-box;" />
      </div>
      <div>
        <label style="display: block; font-size: 11px; font-weight: 600; color: var(--text-muted); margin-bottom: 4px;">承認者</label>
        <select class="approval-step-user" style="width: 100%; padding: 6px 8px; background: var(--bg-card); border: 1px solid rgba(212, 175, 55, 0.25); border-radius: 3px; color: var(--text); font-size: 12px; box-sizing: border-box;">
          <option value="">選択</option>
          <option value="user1">田中太郎</option>
          <option value="user2">佐藤花子</option>
          <option value="user3">鈴木次郎</option>
        </select>
      </div>
      <button class="remove-approval-step" style="padding: 6px 10px; background: transparent; border: 1px solid var(--border); color: var(--text); border-radius: 3px; font-size: 12px; cursor: pointer;">削除</button>
    `;
    container.querySelector('#approval-flow-container').appendChild(stepContainer);
    stepContainer.querySelector('.remove-approval-step').addEventListener('click', () => {
      stepContainer.remove();
    });
  });

  // 保存
  saveBtn.addEventListener('click', async () => {
    const templateData = {
      contract_name: templateNameInput.value,
      contract_description: templateDescInput.value,
      contract_type: templateCategorySelect.value,
      file_path: templateContentInput.value,
      status: 'active',
      contract_start_date: new Date().toISOString(),
    };

    if (!templateData.contract_name) {
      alert('テンプレート名を入力してください');
      return;
    }

    try {
      if (currentTemplateId) {
        await window.aivicApi.update(0, currentTemplateId, templateData);
      } else {
        const saved = await window.aivicApi.save(0, templateData);
        if (saved) currentTemplateId = saved.id;
      }
      loadTemplates();
      alert('テンプレートを保存しました');
    } catch (err) {
      console.error('Save error:', err);
    }
  });

  // キャンセル
  cancelBtn.addEventListener('click', () => {
    currentTemplateId = null;
    templateNameInput.value = '';
    templateDescInput.value = '';
    templateCategorySelect.value = '';
    templateContentInput.value = '';
    statusEl.textContent = 'テンプレートを選択してください';
    updatePreview();
    renderTemplateList();
  });

  // モーダル閉じる
  closeModalBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      deleteConfirmModal.style.display = 'none';
    });
  });

  deleteConfirmModal.addEventListener('click', (e) => {
    if (e.target === deleteConfirmModal) {
      deleteConfirmModal.style.display = 'none';
    }
  });

  // 初期化
  switchTab('basic');
  loadTemplates();
}
